//! World lighting from an HDRI (`RWorld::Hdri`, WP 5.2): split-sum image-based lighting —
//! irradiance as L2 spherical harmonics, radiance prefiltered per GGX roughness into the mips of
//! a cube map, and the BRDF LUT (`assets/brdf_lut.bin`, generated by WP 5.2). The forward
//! shader (WP 5.1) samples [`WorldLighting`]; a constant-colour world never reaches this module.
//!
//! Stub (M5+M6 W0): the signature WP 5.1 calls; WP 5.2 implements it.

use frap_render_scene::{RenderError, RenderScene};

use crate::gpu::Gpu;

/// The HDRI world as the forward shader samples it.
#[non_exhaustive]
pub struct WorldLighting {
    /// Irradiance, L2 spherical harmonics (RGB in `xyz`; 9 coefficients, Blender's world
    /// rotation and strength applied).
    pub sh9: [[f32; 4]; 9],
    /// Radiance prefiltered per roughness, one mip per GGX roughness step (`Rgba16Float`
    /// cube map).
    pub specular: wgpu::TextureView,
    /// Number of mips of [`WorldLighting::specular`].
    pub specular_mips: u32,
    /// The split-sum BRDF LUT (`Rg16Float`, from `assets/brdf_lut.bin`).
    pub brdf_lut: wgpu::TextureView,
    /// The environment as the background shows it (equirectangular, `Rgba16Float`).
    pub background: wgpu::TextureView,
}

/// Builds the world lighting of `scene` when its world is an HDRI (`Ok(None)` otherwise).
pub fn world_lighting(
    gpu: &Gpu,
    scene: &RenderScene,
) -> Result<Option<WorldLighting>, RenderError> {
    let _ = gpu;
    match scene.world {
        frap_render_scene::RWorld::Hdri { .. } => Err(RenderError::Unsupported(
            "HDRI world lighting is not implemented yet (M5, WP 5.2)".into(),
        )),
        _ => Ok(None),
    }
}
